<script lang="ts">import SeriesForm from '$lib/components/workspace/SeriesForm.svelte';let {data,form}=$props();const empty={name:'',description:'',status:'draft',archived:false,members:[]};</script><svelte:head><title>系列 · 站长工作台</title></svelte:head><main><h1>系列</h1>{#if form?.error}<p role="alert">{form.error}</p>{/if}{#if form?.success}<p role="status">{form.success}</p>{/if}<h2>新建系列</h2>{#key JSON.stringify(form?.input)}<SeriesForm value={!form?.input?.id?form?.input??empty:empty} content={data.content}/>{/key}{#each data.series as series}<h2>{series.name}</h2>{#key JSON.stringify([series,form?.input])}<SeriesForm value={form?.input?.id===series.id?form.input:series} content={data.content}/>{/key}{/each}</main>
